std::string weatherTexture(const WeatherState& state) {auto dir=state.definition.find("texDir"),file=state.definition.find("texFile");if(dir==state.definition.end() || file==state.definition.end() || dir->second.empty() || file->second.empty() || file->second=="_")return {};auto path=dir->second+"\\"+file->second;if(!path.ends_with(".blp") && !path.ends_with(".tga"))path+=".blp";return path;}
std::uint32_t weatherHash(std::uint32_t x) {x^=x>>16;x*=0x7feb352du;x^=x>>15;x*=0x846ca68bu;return x^(x>>16);}
float weatherRandom(std::uint32_t value) {return float(weatherHash(value)>>8)*(1.f/16777216.f);}
